// Generated by AI

import type { Location, ClimateSeries, Crop, FarmRequest, AIChatRequest } from "./contracts";
import {
  type SummaryResponse,
  type HistoryResponse,
  type ForecastResponse,
  type RisksResponse,
  type SoilResponse,
  type TerrainResponse,
  type SuitabilityResponse,
  type RotationResponse,
  type ChatResponse,
  type OpenMeteoRawPayload,
  summaryView,
  historyView,
  forecastView,
  risksView,
  soilView,
  terrainView,
  suitabilityView,
  rotationView,
  chatView,
  openMeteoToForecast,
  openMeteoToSummary,
  openMeteoToRisks,
} from "./fastapi";
import municipalities from "@/data/sp-municipalities.json";

const DEFAULT_API_BASE_URL = "https://nasa-challenge-nvrf.onrender.com";
const OPEN_METEO_URLS = [
  "https://api.open-meteo.com/v1/forecast",
  "https://historical-forecast-api.open-meteo.com/v1/forecast",
];

const openMeteoCache = new Map<
  string,
  { expiresAt: number; promise: Promise<OpenMeteoRawPayload> }
>();

async function fetchOpenMeteoDirect(p: Location, days = 7): Promise<OpenMeteoRawPayload> {
  const key = `${p.lat.toFixed(4)},${p.lon.toFixed(4)},${days}`;
  const now = Date.now();
  const cached = openMeteoCache.get(key);
  if (cached && cached.expiresAt > now) return cached.promise;

  const params = new URLSearchParams({
    latitude: String(p.lat),
    longitude: String(p.lon),
    timezone: "America/Sao_Paulo",
    forecast_days: String(days),
    temperature_unit: "celsius",
    wind_speed_unit: "kmh",
    precipitation_unit: "mm",
    current:
      "temperature_2m,relative_humidity_2m,precipitation,wind_speed_10m,wind_gusts_10m,soil_moisture_0_to_1cm,soil_moisture_1_to_3cm,soil_moisture_3_to_9cm",
    daily:
      "temperature_2m_min,temperature_2m_max,temperature_2m_mean,relative_humidity_2m_mean,precipitation_sum,precipitation_probability_max,wind_speed_10m_max,wind_gusts_10m_max,et0_fao_evapotranspiration",
  });

  const promise = (async () => {
    for (const baseUrl of OPEN_METEO_URLS) {
      try {
        const res = await fetch(`${baseUrl}?${params}`, { signal: AbortSignal.timeout(15000) });
        if (!res.ok) continue;
        const json = (await res.json()) as OpenMeteoRawPayload & { error?: boolean };
        if (json && !json.error && (json.daily || json.current)) return json;
      } catch {
        continue;
      }
    }
    throw new Error("The Open-Meteo forecast is temporarily unavailable.");
  })();

  openMeteoCache.set(key, { expiresAt: now + 300_000, promise });
  promise.catch(() => openMeteoCache.delete(key));
  return promise;
}

export const API_CONFIGURED = Boolean(
  import.meta.env["VITE_API_BASE_URL"] || import.meta.env["VITE_API_URL"] || DEFAULT_API_BASE_URL,
);

async function request<T>(
  path: string,
  params?: Record<string, string | number>,
  body?: unknown,
): Promise<T> {
  const base =
    import.meta.env["VITE_API_BASE_URL"] || import.meta.env["VITE_API_URL"] || DEFAULT_API_BASE_URL;
  if (!base) throw new Error("The data service is unavailable.");
  const query = new URLSearchParams();
  for (const [key, value] of Object.entries(params ?? {})) query.set(key, String(value));
  const response = await fetch(base.replace(/\/$/, "") + path + (query.size ? "?" + query : ""), {
    method: body ? "POST" : "GET",
    headers: {
      "Accept-Language": "en",
      ...(body ? { "Content-Type": "application/json" } : {}),
    },
    ...(body ? { body: JSON.stringify(body) } : {}),
    signal: AbortSignal.timeout(path === "/api/v1/ai/chat" ? 60000 : 30000),
  });
  if (!response.ok) {
    const data = await response.json().catch(() => null);
    const code = data?.detail?.code;
    if (code === "outside_sao_paulo") {
      throw new Error("Select a location within the state of São Paulo.");
    }
    if (code === "invalid_request") {
      throw new Error("Check the location, dates, and other inputs, then try again.");
    }
    if (code === "unknown_crop") {
      throw new Error("The previous crop ID is absent from the catalog.");
    }
    if (response.status === 429) {
      throw new Error("Too many requests. Try again in a moment.");
    }
    throw new Error(`Could not load data (HTTP ${response.status}).`);
  }
  return response.json();
}

const coords = (p: Location) => ({ latitude: p.lat, longitude: p.lon });

function planting(body: FarmRequest) {
  const [year, month, day] = body.planting_date.split("-").map(Number);
  return {
    location: coords(body.location),
    planting_year: year,
    planting_month: month,
    planting_day: day,
  };
}

export const api = {
  summary: async (p: Location) => {
    const data = await request<SummaryResponse>("/api/v1/regions/summary", coords(p)).catch(
      () => null,
    );
    if (!data || data.weather?.status === "provider_error") {
      try {
        const raw = await fetchOpenMeteoDirect(p);
        return summaryView(openMeteoToSummary(raw));
      } catch {
        if (data) return summaryView(data);
        throw new Error("Could not load the regional summary.");
      }
    }
    return summaryView(data);
  },
  history: (p: Location, days: number) =>
    request<HistoryResponse>("/api/v1/climate/history", { ...coords(p), days }).then(historyView),
  series: (p: Location, startYear: number, endYear: number, month: number, metric: string) =>
    request<ClimateSeries>("/api/v1/climate/series", {
      ...coords(p),
      start_year: startYear,
      end_year: endYear,
      ...(month ? { month } : {}),
      metric,
      group_by: "month",
    }),
  forecast: async (p: Location) => {
    const data = await request<ForecastResponse>("/api/v1/weather/forecast", coords(p)).catch(
      () => null,
    );
    if (!data || data.status === "provider_error" || !data.daily?.length) {
      try {
        const raw = await fetchOpenMeteoDirect(p);
        return forecastView(openMeteoToForecast(raw));
      } catch {
        if (data) return forecastView(data);
        throw new Error("The Open-Meteo forecast is temporarily unavailable.");
      }
    }
    return forecastView(data);
  },
  risks: async (p: Location, cropId?: string) => {
    const data = await request<RisksResponse>("/api/v1/risks", {
      ...coords(p),
      ...(cropId ? { crop_id: cropId } : {}),
    }).catch(() => null);
    if (!data || data.status === "provider_error" || !data.period_start) {
      try {
        const raw = await fetchOpenMeteoDirect(p);
        return risksView(openMeteoToRisks(raw, cropId));
      } catch {
        if (data) return risksView(data);
        throw new Error("Could not load agro-environmental risks.");
      }
    }
    return risksView(data);
  },
  soil: (p: Location) => request<SoilResponse>("/api/v1/soil", coords(p)).then(soilView),
  terrain: (p: Location) =>
    request<TerrainResponse>("/api/v1/terrain", coords(p)).then(terrainView),
  crops: () => request<Crop[]>("/api/v1/crops"),
  suitability: (body: FarmRequest) =>
    request<SuitabilityResponse>("/api/v1/crops/suitability", undefined, planting(body)).then(
      suitabilityView,
    ),
  rotation: (body: FarmRequest) =>
    request<RotationResponse>("/api/v1/crops/rotation", undefined, {
      ...planting(body),
      previous_crop_name: body.previous_crop_name,
      objective: body.priority,
      previous_planting_date: body.previous_planting_date || undefined,
    }).then(rotationView),
  chat: (body: AIChatRequest) =>
    request<ChatResponse>("/api/v1/ai/chat", undefined, {
      message:
        body.selected_crop && body.message.length + body.selected_crop.length + 20 <= 2000
          ? `Selected crop: ${body.selected_crop}.\n\n${body.message}`
          : body.message,
      location: coords(body.location),
      history: body.history.slice(-8).map(({ role, content }) => ({ role, content })),
    }).then(chatView),
};

const normalize = (text: string) =>
  text
    .normalize("NFD")
    .replace(/\p{Diacritic}/gu, "")
    .toLowerCase()
    .trim();

export async function geocode(query: string): Promise<Location[]> {
  const match = query.trim().match(/^(-?\d+(?:\.\d+)?)\s*[,;]\s*(-?\d+(?:\.\d+)?)$/);
  if (match) return [{ lat: Number(match[1]), lon: Number(match[2]), name: query }];
  const name = normalize(query)
    .replace(/,\s*sp$/, "")
    .trim();
  if (!name) return [];
  const matches = municipalities.filter(([city]) => normalize(String(city)).includes(name));
  const exact = matches.find(([city]) => normalize(String(city)) === name);
  if (exact || matches.length) {
    return (exact ? [exact] : matches.slice(0, 5)).map(([city, lat, lon]) => ({
      lat: Number(lat),
      lon: Number(lon),
      name: `${city}, SP`,
    }));
  }

  const base = import.meta.env["VITE_GEOCODING_URL"];
  if (!base) return [];
  const url = new URL(base);
  for (const [key, value] of Object.entries({
    format: "json",
    addressdetails: "1",
    limit: "5",
    countrycodes: "br",
    "accept-language": "en",
    q: query,
  }))
    url.searchParams.set(key, value);
  const response = await fetch(url, { signal: AbortSignal.timeout(15000) });
  if (!response.ok) throw new Error("Could not search for the address.");
  const rows = (await response.json()) as { lat: string; lon: string; display_name: string }[];
  return rows.map((row) => ({
    lat: Number(row.lat),
    lon: Number(row.lon),
    name: row.display_name,
  }));
}
